    (u, v) = (panel['u'], panel['v' + str(k)])
    if k == 1:

        def features(z, p):
            w = p[0] * z + p[1:]
            return _ones(np.c_[z, w / (1 + abs(w))])
        start = [0.84, 0.0, 0.0, 0.0, 0.0]
    else:

        def features(z, p):
            return _ones(np.c_[z, np.cos(p[0] * z + p[1:])])
        start = [1.27, 0.0, 0.0, 0.0, 0.0]

    def residual(p):
        d = features(u, p)
